40	import org.springframework.samples.petclinic.service.ClinicService;
41	import org.springframework.security.access.prepost.PreAuthorize;
42	import org.springframework.web.bind.annotation.CrossOrigin;
43	import org.springframework.web.bind.annotation.RequestMapping;
44	import org.springframework.web.bind.annotation.RestController;
45	import org.springframework.web.util.UriComponentsBuilder;
46	
47	import jakarta.transaction.Transactional;
48	
49	/**
50	 * @author Vitaliy Fedoriv
51	 */
52	
53	@RestController
54	@CrossOrigin(exposedHeaders = "errors, content-type")
55	@RequestMapping("/api")
56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    private final ClinicService clinicService;
59	
60	    private final OwnerMapper ownerMapper;
61	
62	    private final PetMapper petMapper;
63	
64	    private final VisitMapper visitMapper;
65	
66	    public OwnerRestControllerV1(ClinicService clinicService,
67	                                 OwnerMapper ownerMapper,
68	                                 PetMapper petMapper,
69	                                 VisitMapper visitMapper) {
70	        this.clinicService = clinicService;
71	        this.ownerMapper = ownerMapper;
72	        this.petMapper = petMapper;
73	        this.visitMapper = visitMapper;
74	    }
75	
76	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
77	    @Override
78	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
79	        Collection<Owner> owners;
80	        if (lastName != null) {
81	            owners = this.clinicService.findOwnerByLastName(lastName);
82	        } else {
83	            owners = this.clinicService.findAllOwners();
84	        }
85	        if (owners.isEmpty()) {
86	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
87	        }
88	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
94	        Owner owner = this.clinicService.findOwnerById(ownerId);
95	        if (owner == null) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
104	        HttpHeaders headers = new HttpHeaders();
105	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
106	        if (isDuplicateTelephone(owner)) {
107	            throw new DuplicateOwnerException("An owner with telephone "
108	                + owner.getTelephone() + " already exists");
109	        }
110	        this.clinicService.saveOwner(owner);
111	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
112	        headers.setLocation(UriComponentsBuilder.newInstance()
113	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
114	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
115	    }
116	
117	    /**
118	     * Determines whether any other owner already uses the candidate's telephone number.
119	     *
120	     * @param candidate the owner about to be created
121	     * @return {@code true} if an owner with the same telephone is already present in the data store
122	     */
123	    private boolean isDuplicateTelephone(Owner candidate) {
124	        return this.clinicService.findAllOwners().stream()
125	            .anyMatch(existing ->
126	                Objects.equals(existing.getTelephone(), candidate.getTelephone()));
127	    }
128	
129	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
130	    @Override
131	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
132	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
133	        if (currentOwner == null) {
134	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
135	        }
136	        currentOwner.setAddress(ownerFieldsDto.getAddress());
137	        currentOwner.setCity(ownerFieldsDto.getCity());
138	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
139	        currentOwner.setLastName(ownerFieldsDto.getLastName());
140	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
141	        this.clinicService.saveOwner(currentOwner);
142	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
143	    }
144	
145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Transactional
147	    @Override
148	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
149	        Owner owner = this.clinicService.findOwnerById(ownerId);
150	        if (owner == null) {
151	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
152	        }
153	        this.clinicService.deleteOwner(owner);
154	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
155	    }
156	
157	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
158	    @Override
159	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
160	        Owner owner = this.clinicService.findOwnerById(ownerId);
161	        if (owner == null) {
162	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
163	        }
164	        HttpHeaders headers = new HttpHeaders();
165	        Pet pet = petMapper.toPet(petFieldsDto);
166	        owner.setId(ownerId);
167	        pet.setOwner(owner);
168	        pet.getType().setName(null);
169	        this.clinicService.savePet(pet);
170	        PetDto petDto = petMapper.toPetDto(pet);
171	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
172	            .buildAndExpand(pet.getId()).toUri());
173	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
174	    }
175	
176	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
177	    @Override
178	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
179	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
180	        if (currentOwner != null) {
181	            Pet currentPet = this.clinicService.findPetById(petId);
182	            if (currentPet != null) {
183	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
184	                currentPet.setName(petFieldsDto.getName());
185	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
186	                this.clinicService.savePet(currentPet);
187	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
188	            }
189	        }
190	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
191	    }
192	
193	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
194	    @Override
195	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
196	        HttpHeaders headers = new HttpHeaders();
197	        Visit visit = visitMapper.toVisit(visitFieldsDto);
198	        Pet pet = new Pet();
199	        pet.setId(petId);
200	        visit.setPet(pet);
201	        this.clinicService.saveVisit(visit);
202	        VisitDto visitDto = visitMapper.toVisitDto(visit);
203	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
204	            .buildAndExpand(visit.getId()).toUri());
205	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
206	    }
207	
208	
209	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
210	    @Override
211	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
212	        Owner owner = this.clinicService.findOwnerById(ownerId);
213	        if (owner != null) {
214	            Pet pet = owner.getPet(petId);
215	            if (pet != null) {
216	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
217	            }
218	        }
219	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
220	    }
221	}
